// ScentOS service worker — deliberately minimal and hand-written rather than
// generated by a build plugin (the popular next-pwa packages have gone
// largely unmaintained), so it's easy to reason about and extend.
//
// Strategy:
//  - App icons & static assets: cache-first (they're versioned by Next.js build hash)
//  - Everything else (pages, API calls): network-first, falling back to cache
//    when offline, so users always see fresh data when online.

const CACHE_NAME = 'scentos-v1';
const PRECACHE_URLS = ['/', '/icons/icon-192.png', '/icons/icon-512.png'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(PRECACHE_URLS)),
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k))),
    ),
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const isStaticAsset = /\.(png|jpg|jpeg|svg|webp|ico|woff2?)$/.test(new URL(request.url).pathname);

  if (isStaticAsset) {
    event.respondWith(
      caches.match(request).then(
        (cached) =>
          cached ||
          fetch(request).then((response) => {
            const copy = response.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
            return response;
          }),
      ),
    );
    return;
  }

  event.respondWith(
    fetch(request)
      .then((response) => {
        const copy = response.clone();
        caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
        return response;
      })
      .catch(() => caches.match(request)),
  );
});
